def is_bored(str):
    delimiters = ['.', '?', '!']
    count = 0
    for deli in delimiters:
        sentences = str.split(deli)
        for sentence in sentences:
            words = sentence.lstrip().split() # remove leading whitespace and split into words
            if len(words) > 0 and words[0] == 'I':
                count += 1
    return count

