def is_multiply_prime(num):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_count = 0
    for i in range(2, num):
        if is_prime(i) and num % i == 0:
            prime_count += 1
            if prime_count == 3:
                return True

    return False

