def even_odd_count(num):

    number = abs(int(num))

    even = 0
    odd = 0

    while (number > 0): 

        rem = number % 10

        number = int(number / 10)

        if (rem % 2 == 0): 
            even += 1 
        else: 
            odd += 1

    return (even, odd)

