def even_odd_count(num):
    if num == 0:
        return (1, 0)
    num = abs(num)
    even, odd = 0, 0
    while num != 0:
        last_digit = num % 10
        num = num // 10
        if last_digit % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

