def even_odd_count(num):
    odd_cnt, even_cnt = 0, 0
    for c in str(abs(num)):
        val = int(c)
        if val % 2:
            odd_cnt += 1
        else:
            even_cnt += 1

    return (odd_cnt, even_cnt)

