def triples_sum_to_zero(l):
    l.sort()
    for i in range(len(l)-2):
        if i > 0 and l[i] == l[i-1]:
            continue
        left = i + 1
        right = len(l) - 1
        while left < right:
            total = l[i] + l[left] + l[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False

