        right = len(l)-1
        while left < right:
            s = l[i] + l[left] + l[right]
            if s == 0:
                res.append((l[i], l[left], l[right]))
                left+=1
                while l[left] == l[left-1] and left < right:
                    left+=1
            elif s > 0:
                right -= 1
            else:
                left += 1
    return res

