class Tokenizer:
    def __init__(self, max_vocab_size=200):
        self.max_vocab_size = max_vocab_size
        self.word_to_id = {}
        self.id_to_word = {}
        self.most_common_words = []

    def tokenize(self, text):
        # do not change
        # Split text into words by spaces
        return text.lower().split()

    def build_vocabulary(self, corpus):
        '''
        corpus: a list of strings (string denotes a sentence composed of words seperated by spaces)
        '''
        counter = {}
        for sentence in corpus:
            tokens = self.tokenize(sentence)
            for token in tokens:
                counter[token] = counter.get(token, 0) + 1
        self.most_common_words = sort(counter, reverse=True, key=counter.get)[:max_vocab_size]
